const uploadCache=new Map();
async function uploadImage(input,mime){const embedded=input?.bytes&&typeof input.bytes!=='function'?input.bytes:null;const body=embedded||input;const type=mime||input?.mime||input?.type;let bytes;if(embedded)bytes=embedded;else if(body instanceof Uint8Array)bytes=body;else if(typeof body?.arrayBuffer==='function')bytes=new Uint8Array(await body.arrayBuffer());if(bytes){if(bytes.byteLength>5*1024*1024)throw Error('이미지는 5MB 이하만 업로드할 수 있습니다.');const digest=crypto.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join(''):null;if(digest&&uploadCache.has(digest))return uploadCache.get(digest);const promise=api('/uploads',{method:'POST',body:bytes,headers:{'Content-Type':type||'application/octet-stream'}}).then(v=>v.url);if(digest){uploadCache.set(digest,promise);while(uploadCache.size>32)uploadCache.delete(uploadCache.keys().next().value)}try{return await promise}catch(e){if(digest)uploadCache.delete(digest);throw e}}return (await api('/uploads',{method:'POST',body,headers:{'Content-Type':type||'application/octet-stream'}})).url;}
