async function refreshAccount(){if(!account)return;const epoch=authEpoch,owner=account.id;const results=await Promise.all([api('/account'),api('/friends'),api('/notifications'),api('/campaign-shares')]);if(epoch!==authEpoch||account?.id!==owner||results[0].profile.id!==owner)return;account=results[0].profile;if(results[0].auth)authMeta=results[0].auth;account.preferences??={};for(const [key,desired] of preferencePending)account.preferences[key]=desired;friends=results[1].friends;notifications=results[2].notifications;shared=results[3].campaigns;updateStatus();}
